/**
 * Model File
 * Файл (изображения, шрифты и т.д.)
 */
export type File = $Result.DefaultSelection<Prisma.$FilePayload>
/**
 * Model Franchise
 * Франшиза — группа связанных аниме
 * Определяется через REST API /api/animes/{id}/franchise
 * Все аниме в одном графе = одна франшиза
 */
export type Franchise = $Result.DefaultSelection<Prisma.$FranchisePayload>
/**
 * Model Anime
 * Аниме-тайтл
 */
export type Anime = $Result.DefaultSelection<Prisma.$AnimePayload>
/**
 * Model Genre
 * Жанр
 */
export type Genre = $Result.DefaultSelection<Prisma.$GenrePayload>
/**
 * Model GenreOnAnime
 * Связь жанров и аниме (many-to-many)
 */
export type GenreOnAnime = $Result.DefaultSelection<Prisma.$GenreOnAnimePayload>
/**
 * Model Theme
 * Тема аниме (Жестокость, Городское фэнтези, Школа и т.д.)
 */
export type Theme = $Result.DefaultSelection<Prisma.$ThemePayload>
/**
 * Model ThemeOnAnime
 * 
 */
export type ThemeOnAnime = $Result.DefaultSelection<Prisma.$ThemeOnAnimePayload>
/**
 * Model AnimeRelation
 * Связь между двумя аниме (сиквел, приквел, спин-офф и т.д.)
 */
export type AnimeRelation = $Result.DefaultSelection<Prisma.$AnimeRelationPayload>
/**
 * Model Season
 * Сезон аниме (TV, OVA, Movie и т.д.)
 */
export type Season = $Result.DefaultSelection<Prisma.$SeasonPayload>
/**
 * Model AudioTrack
 * Аудиодорожка эпизода
 */
export type AudioTrack = $Result.DefaultSelection<Prisma.$AudioTrackPayload>
/**
 * Model SubtitleTrack
 * Субтитры эпизода
 */
export type SubtitleTrack = $Result.DefaultSelection<Prisma.$SubtitleTrackPayload>
/**
 * Model SubtitleFont
 * Шрифт для ASS субтитров
 */
export type SubtitleFont = $Result.DefaultSelection<Prisma.$SubtitleFontPayload>
/**
 * Model Chapter
 * Глава эпизода (для навигации и автопропуска)
 */
export type Chapter = $Result.DefaultSelection<Prisma.$ChapterPayload>
/**
 * Model Episode
 * Эпизод (серия)
 */
export type Episode = $Result.DefaultSelection<Prisma.$EpisodePayload>
/**
 * Model WatchProgress
 * Прогресс просмотра
 */
export type WatchProgress = $Result.DefaultSelection<Prisma.$WatchProgressPayload>
/**
 * Model Settings
 * Настройки приложения (singleton)
 */
export type Settings = $Result.DefaultSelection<Prisma.$SettingsPayload>
/**
 * Model EncodingProfile
 * Профиль кодирования
 */
export type EncodingProfile = $Result.DefaultSelection<Prisma.$EncodingProfilePayload>
/**
 * Model ImportQueueItem
 * Элемент очереди импорта
 * Хранит настройки из wizard'а для последовательной обработки
 */
export type ImportQueueItem = $Result.DefaultSelection<Prisma.$ImportQueueItemPayload>
/**
 * Model Subscription
 * Подписка на библиотеку другого пользователя (P2P Sharing)
 */
export type Subscription = $Result.DefaultSelection<Prisma.$SubscriptionPayload>
/**
 * Model Tracker
 * Удалённый трекер в федеративной сети
 */
export type Tracker = $Result.DefaultSelection<Prisma.$TrackerPayload>
/**
 * Model FederatedContent
 * Федеративный контент — импортированный из другого трекера
 */
export type FederatedContent = $Result.DefaultSelection<Prisma.$FederatedContentPayload>
/**
 * Model FederationSettings
 * Настройки федерации (singleton)
 */
export type FederationSettings = $Result.DefaultSelection<Prisma.$FederationSettingsPayload>
/**
 * Model UserStats
 * Статистика пользователя (singleton)
 */
export type UserStats = $Result.DefaultSelection<Prisma.$UserStatsPayload>
/**
 * Model DailyStats
 * Дневная статистика
 */
export type DailyStats = $Result.DefaultSelection<Prisma.$DailyStatsPayload>
/**
 * Model UserReputation
 * Репутация пользователя (singleton)
 */
export type UserReputation = $Result.DefaultSelection<Prisma.$UserReputationPayload>
/**
 * Model UserAchievement
 * Разблокированное достижение пользователя
 */
export type UserAchievement = $Result.DefaultSelection<Prisma.$UserAchievementPayload>
/**
 * Model AchievementProgress
 * Прогресс достижения
 */
export type AchievementProgress = $Result.DefaultSelection<Prisma.$AchievementProgressPayload>
/**
 * Model UserBonusPoints
 * Бонусные очки пользователя (singleton)
 */
export type UserBonusPoints = $Result.DefaultSelection<Prisma.$UserBonusPointsPayload>
/**
 * Model BonusTransaction
 * Транзакция бонусных очков
 */
export type BonusTransaction = $Result.DefaultSelection<Prisma.$BonusTransactionPayload>
/**
 * Model LocalUserProfile
 * Профиль пользователя для P2P синхронизации (singleton)
 * Заменяет OrbitDB UserProfileDB — хранится в SQLite, публикуется через IPNS
 */
export type LocalUserProfile = $Result.DefaultSelection<Prisma.$LocalUserProfilePayload>
/**
 * Model Friend
 * Друг в P2P сети
 * Хранит информацию о принятых друзьях для PresenceSync
 */
export type Friend = $Result.DefaultSelection<Prisma.$FriendPayload>
/**
 * Model FriendRequest
 * Запрос в друзья (входящий/исходящий)
 */
export type FriendRequest = $Result.DefaultSelection<Prisma.$FriendRequestPayload>

